// Extrai mensagem do payload da Meta
const payload = $input.first().json.body;

// Verifica se é um evento de mensagem
const entry   = payload?.entry?.[0];
const change  = entry?.changes?.[0]?.value;
const msg     = change?.messages?.[0];
const status  = change?.statuses?.[0];

if (!msg && !status) {
  return [{ json: { tipo: 'ignorar', motivo: 'Sem mensagem ou status reconhecível' } }];
}

// Evento de status de entrega (delivered / read / failed)
if (status && !msg) {
  return [{
    json: {
      tipo:       'status',
      message_id: status.id,
      status_api: status.status,
      telefone:   '+' + status.recipient_id.replace(/\D/g, '')
    }
  }];
}

// Mensagem de texto do membro
if (msg.type !== 'text') {
  return [{ json: { tipo: 'ignorar', motivo: 'Mensagem não é texto: ' + msg.type } }];
}

const texto    = msg.text?.body || '';
const telefone = '+' + msg.from.replace(/\D/g, '');

// Normaliza: remove acentos, lowercase, trim
function normalizar(t) {
  return t.toLowerCase().trim()
    .replace(/[áàãâ]/g,'a').replace(/[éê]/g,'e')
    .replace(/[í]/g,'i').replace(/[óôõ]/g,'o')
    .replace(/[úü]/g,'u').replace(/ç/g,'c');
}

const textoNorm = normalizar(texto);

// Palavras-chave de confirmação
const confirmar = ['confirmar','sim','confirmo','presente','ok','vou'];
const recusar   = ['nao posso','não posso','nao','não','faltarei','ausente','impossivel','impossível'];

let decisao = 'nao_reconhecido';
for (const p of confirmar) { if (textoNorm.includes(normalizar(p))) { decisao = 'confirmado'; break; } }
if (decisao === 'nao_reconhecido') {
  for (const p of recusar) { if (textoNorm.includes(normalizar(p))) { decisao = 'recusado'; break; } }
}

return [{
  json: {
    tipo:       'mensagem',
    telefone,
    texto,
    textoNorm,
    decisao,
    message_id: msg.id
  }
}];

